        _, borrow_date = self.borrowed_books.pop(book_id)
        self.user_loans[user].remove(book_id)

        due_date = borrow_date + timedelta(days=self.loan_days)
        delay_days = self._count_business_days(start_exclusive=due_date, end_inclusive=day)

        fine = delay_days * self.daily_fine
        if fine > 0:
            self.fines[user] += fine

        return fine

    def unpaid_fines(self, user: str) -> float:
        return self.fines[user]

    def pay(self, user: str) -> None:
        """Pay all fines of the user."""
        self.fines[user] = 0.0

    @staticmethod
    def _count_business_days(start_exclusive: date, end_inclusive: date) -> int:
        """Count weekdays (Monday through Friday) in the range (start_exclusive, end_inclusive]."""
        if end_inclusive <= start_exclusive:
